function buildJourneyGroups(){const series=state.items.filter(x=>x.type!=="movie"&&!x.completed);const started=series.filter(x=>(Number(x.progress?.season)||1)>1||(Number(x.progress?.episode)||1)>1);const notStarted=series.filter(x=>(Number(x.progress?.season)||1)===1&&(Number(x.progress?.episode)||1)===1);const primary=["Occidentale","Turque","Asiatique"],order=[...primary,"Anime","Autres","À classer"];const pools=Object.fromEntries(order.map(c=>[c,started.filter(x=>(x.nationalityTag||"À classer")===c).sort((a,b)=>String(a.name||"").localeCompare(String(b.name||""),"fr"))]));const balancedCount=Math.min(...primary.map(c=>pools[c].length));const groups=[[],[],[]];let offset=0;for(const cat of primary){pools[cat].slice(0,balancedCount).forEach((item,index)=>groups[(index+offset)%3].push(item));offset=(offset+balancedCount)%3;}for(const cat of order.slice(3)){pools[cat].forEach((item,index)=>groups[(index+offset)%3].push(item));offset=(offset+pools[cat].length)%3;}groups.forEach(g=>g.sort((a,b)=>order.indexOf(a.nationalityTag||"À classer")-order.indexOf(b.nationalityTag||"À classer")||String(a.name||"").localeCompare(String(b.name||""),"fr")));const included=new Set(groups.flat().map(x=>String(x.id)));const extras=started.filter(x=>!included.has(String(x.id))).sort((a,b)=>order.indexOf(a.nationalityTag||"À classer")-order.indexOf(b.nationalityTag||"À classer")||String(a.name||"").localeCompare(String(b.name||""),"fr"));groups.push(extras);return{started,notStarted,groups,extras,balancedCount,order};}
function renderJourneyGroups(){const host=$("journey-groups");if(!host)return;const {started,notStarted,groups,extras,balancedCount,order}=buildJourneyGroups();const row=x=>'<div class="journey-series" data-journey-id="'+esc(String(x.id))+'" role="button" tabindex="0" aria-label="Ouvrir la fiche de '+esc(x.name)+'"><img src="'+esc(img(x.poster,"w92"))+'" alt="" onerror="this.style.visibility=\'hidden\'"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.nationalityTag||"À classer")+' · S'+(x.progress?.season||1)+' E'+(x.progress?.episode||1)+' à venir</small></div><span class="journey-open-hint" aria-hidden="true">›</span></div>';const counts=Object.fromEntries(order.map(c=>[c,started.filter(x=>(x.nationalityTag||"À classer")===c).length]));const summary='<div class="journey-summary"><div><strong>'+started.length+' séries commencées · '+notStarted.length+' non entamées</strong><small>'+groups.slice(0,3).reduce((n,g)=>n+g.length,0)+' dans les groupes équilibrés · '+extras.length+' en groupe 4</small></div><div class="journey-category-counts">'+order.filter(c=>counts[c]).map(c=>'<span>'+c+' <b>'+counts[c]+'</b></span>').join("")+'</div></div>';const makeGroup=(g,i,title,subtitle)=>{const categories=order.map(cat=>({cat,items:g.filter(x=>(x.nationalityTag||"À classer")===cat)})).filter(x=>x.items.length);const chosen=state.journeyDraws?.[String(i)];const validChosen=chosen&&g.some(x=>String(x.id)===String(chosen.id));const result=validChosen?'<div class="journey-draw-result"><span class="journey-result-label">TA SÉLECTION</span>'+row(g.find(x=>String(x.id)===String(chosen.id)))+'</div>':"";let seen=0;const content=categories.map(({cat,items})=>'<section class="journey-category"><h4>'+cat+' <span>'+items.length+'</span></h4>'+items.map(item=>{const markup=row(item);const hidden=seen++>=5;return hidden?markup.replace('class="journey-series"','class="journey-series journey-series-extra hidden"'):markup;}).join("")+'</section>').join("");const more=g.length>5?'<button type="button" class="show-more journey-show-more" data-journey-expand="'+i+'">Voir plus ('+(g.length-5)+')</button>':"";return'<details class="journey-group" '+(state.journeyOpen?.[String(i)]?'open':'')+'><summary class="journey-group-summary"><span><strong>'+title+'</strong><small>'+g.length+' série'+(g.length>1?"s":"")+' · '+subtitle+'</small></span><span class="journey-chevron">⌄</span></summary><div class="journey-group-content"><div class="journey-group-head"><span class="muted">SÉRIES CLASSÉES PAR ÉTIQUETTE</span>'+(i<4?'<button type="button" class="journey-draw-btn" data-journey-draw="'+i+'" '+(!g.length?"disabled":"")+'><span aria-hidden="true">⤨</span> TIRER AU SORT</button>':"")+'</div>'+result+(content||'<p class="muted">Aucune série dans ce groupe.</p>')+more+'</div></details>';};const warning=balancedCount===0&&started.length?'<p class="journey-warning">Pour équilibrer les trois premiers groupes, il faut au moins une série commencée dans chacune des catégories occidentale, turque et asiatique.</p>':"";const groupsMarkup=summary+warning+'<div class="journey-groups-grid">'+groups.slice(0,3).map((g,i)=>makeGroup(g,i,"GROUPE "+(i+1),"équilibré")).join("")+'</div>'+makeGroup(extras,3,"GROUPE 4 — EN ATTENTE D’ÉQUILIBRAGE","séries commencées")+makeGroup(notStarted,4,"SÉRIES NON ENTAMÉES","en attente");const hist=Array.isArray(state.journeyHistory)?state.journeyHistory:[];const historyMarkup=hist.length?'<div class="journey-history-list">'+hist.slice(0,30).map((h,i)=>'<div class="journey-history-entry"><button type="button" class="journey-history-card" data-journey-history-open="'+esc(String(h.id))+'"><strong>'+esc(h.name)+'</strong><small>'+esc(h.group||"Groupe")+' · '+esc(h.date||"")+'</small></button><button type="button" class="journey-history-delete" data-journey-history-delete="'+i+'" aria-label="Retirer">×</button></div>').join("")+'</div><button type="button" class="link-btn journey-history-clear" data-journey-history-clear>Effacer</button>':'<p class="muted">Les séries tirées dans les groupes apparaîtront ici.</p>';host.innerHTML='<nav class="journey-history-tabs"><button type="button" data-journey-view="groups" class="'+((state.journeyHistoryView||"groups")==="groups"?"active":"")+'">Groupes</button><button type="button" data-journey-view="history" class="'+((state.journeyHistoryView||"groups")==="history"?"active":"")+'">Historique <span>'+hist.length+'</span></button></nav>'+((state.journeyHistoryView||"groups")==="history"?historyMarkup:groupsMarkup);if(!started.length&&!notStarted.length&&(state.journeyHistoryView||"groups")==="groups")host.innerHTML+='<p class="muted">Aucune série à afficher dans les groupes pour le moment.</p>';}
function drawJourneyGroup(index){const {groups}=buildJourneyGroups();const group=groups[index];if(!group?.length){toast("Ce groupe ne contient aucune série à tirer.");return;}const previous=state.journeyDraws?.[String(index)]?.id;let pool=group.length>1?group.filter(x=>String(x.id)!==String(previous)):group;const chosen=pool[Math.floor(Math.random()*pool.length)];state.journeyDraws=state.journeyDraws||{};state.journeyDraws[String(index)]={id:chosen.id};state.journeyHistory=Array.isArray(state.journeyHistory)?state.journeyHistory:[];state.journeyHistory.unshift({id:String(chosen.id),name:chosen.name,group:index===3?"Groupe 4":index===4?"Non entamées":"Groupe "+(index+1),date:new Date().toLocaleDateString("fr-FR"),addedAt:Date.now()});state.journeyHistory=state.journeyHistory.slice(0,100);state.journeyHistoryView="groups";state.journeyOpen=state.journeyOpen||{};state.journeyOpen[String(index)]=true;save();renderJourneyGroups();const details=$("journey-groups")?.querySelectorAll(".journey-group")[index];if(details)details.open=true;details?.querySelector(".journey-draw-result")?.scrollIntoView({behavior:"smooth",block:"nearest"});}
function classifySeriesNationality(d){const codes=[...(d?.origin_country||[]),...(d?.production_countries||[]).map(x=>x.iso_3166_1).filter(Boolean)].map(x=>String(x).toUpperCase());const genres=d?.genres||[];const animation=genres.some(g=>Number(g.id)===16);if(animation&&(codes.includes("JP")||d?.original_language==="ja"))return "Anime";if(codes.includes("TR")||d?.original_language==="tr")return "Turque";const asian=new Set(["JP","KR","CN","TW","HK","MO","TH","IN","ID","MY","PH","SG","VN","KH","LA","MM","BD","NP","LK","PK","MN","BT","BN","TL","KP"]);if(codes.some(c=>asian.has(c))||["ko","zh","th","hi","id","ms","vi"].includes(d?.original_language))return "Asiatique";const western=new Set(["US","GB","CA","AU","NZ","FR","DE","ES","IT","PT","NL","BE","CH","AT","IE","SE","NO","DK","FI","IS","PL","CZ","SK","HU","RO","BG","GR","HR","SI","RS","UA","RU","MX","BR","AR","CL","CO","UY","ZA"]);if(codes.some(c=>western.has(c)))return "Occidentale";return "Autres";}async function loadSeriesDetails(){if(seriesDetailsBusy)return;seriesDetailsBusy=true;let changed=false;try{for(const item of state.items){if(item.type==="movie")continue;if(!item.tmdbId){if(item.nationalityTag!=="Autres"){item.nationalityTag="Autres";changed=true;}continue;}if(item.cachedDetails){const tag=item.nationalityManual?item.nationalityTag:classifySeriesNationality(item.cachedDetails);if(item.nationalityTag!==tag){item.nationalityTag=tag;changed=true;}continue;}if(!state.token)continue;detailsLoading.add(item.id);try{const d=await tmdb("/tv/"+item.tmdbId+"?language="+(state.language||"fr-FR"));item.cachedDetails=d;if(!item.nationalityManual)item.nationalityTag=classifySeriesNationality(d);changed=true;}catch(e){}finally{detailsLoading.delete(item.id);}}}finally{seriesDetailsBusy=false;if(changed){save();render();}}}
async function tmdb(path){if(!state.token)throw Error("Ajoute ton jeton TMDB dans les paramètres.");let r=await fetch(API+path,{headers:{Authorization:"Bearer "+state.token,accept:"application/json"}});if(!r.ok)throw Error(r.status===401?"Jeton TMDB invalide. Vérifie-le dans les paramètres.":"TMDB indisponible ("+r.status+").");return r.json();}
function dateYear(d){return d?String(d).slice(0,4):"Année inconnue";}
