let q=el.search.value.trim();if(!q)return;
if(!state.token){toast("Ajoute d'abord ton jeton TMDB dans les paramètres.");el.settings.showModal();return;}
el.searchBtn.disabled=true;el.searchBtn.textContent="RECHERCHE...";el.results.classList.remove("hidden");$("search-close")?.classList.remove("hidden");el.results.innerHTML='<p class="muted">Recherche en cours…</p>';
