function parseLetterboxdCSV(text){
 const rows=[];let row=[],cell="",quoted=false;
 for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch=='"'&&text[i+1]=='"'){cell+='"';i++;}else if(ch=='"')quoted=false;else cell+=ch;}else{if(ch=='"')quoted=true;else if(ch==','){row.push(cell);cell="";}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell="";}else if(ch!=='\r')cell+=ch;}}
 row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)return [];
 const headers=rows.shift().map(v=>v.trim().toLowerCase());const titleIndex=headers.indexOf("name");const yearIndex=headers.indexOf("year");if(titleIndex<0)throw Error("CSV Letterboxd invalide : colonne Name manquante.");
 return rows.map(r=>({name:(r[titleIndex]||"").trim(),year:yearIndex>=0?(r[yearIndex]||"").trim():""})).filter(x=>x.name);
}
$("letterboxd-file").addEventListener("change",async e=>{
 const files=Array.from(e.target.files||[]);if(!files.length)return;
 if(!state.token){toast("Ajoute d'abord ton jeton TMDB dans les paramètres.");el.settings.showModal();e.target.value="";return;}
 try{
 let records=[];for(const f of files){if(f.size>10*1024*1024)throw Error("Un CSV dépasse 10 Mo.");records=records.concat(parseLetterboxdCSV(await f.text()));}
 const norm=v=>String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("fr").replace(/[^a-z0-9]+/g," ").trim();
 const unique=new Map();records.forEach(r=>unique.set(norm(r.name)+"|"+r.year,r));
 let added=0,skipped=0,updated=0;
 for(const r of unique.values()){
  let found=state.items.find(x=>x.type==="movie"&&norm(x.name)===norm(r.name)&&(!r.year||String(x.year||"")===r.year));
  if(found){updated++;continue;}
  const q="/search/movie?query="+encodeURIComponent(r.name)+"&language="+(state.language||"fr-FR")+(r.year?"&year="+encodeURIComponent(r.year):"");
  const results=await tmdb(q);const candidates=results.results||[];
  const hit=candidates.find(x=>norm(x.title)===norm(r.name)&&(!r.year||String((x.release_date||"").slice(0,4))===r.year))||candidates.find(x=>norm(x.title)===norm(r.name))||candidates[0];
  if(!hit){skipped++;continue;}
  const duplicate=state.items.find(x=>x.type==="movie"&&String(x.tmdbId||"")===String(hit.id));
  if(duplicate){updated++;continue;}
  const detail=await tmdb("/movie/"+encodeURIComponent(hit.id)+"?language="+(state.language||"fr-FR"));state.items.push({id:(crypto.randomUUID&&crypto.randomUUID())||Date.now()+"-"+Math.random(),tmdbId:String(hit.id),type:"movie",name:detail.title||hit.title||r.name,poster:detail.poster_path||hit.poster_path||null,year:(detail.release_date||hit.release_date||"").slice(0,4)||r.year||null,active:true,completed:false,movieCategory:inferMovieCategory(detail),movieCategoryChecked:true,progress:{minutes:0},lastEpisode:null,addedAt:Date.now(),letterboxdImported:true});
  added++;
 }
 save();render();toast("Import Letterboxd : "+added+" film(s) ajouté(s), "+updated+" déjà présent(s), "+skipped+" introuvable(s).");
 }catch(err){toast(err.message||"Import Letterboxd impossible.");}finally{e.target.value="";}
});

$("serializd-file").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;if(!state.token){toast("Ajoute d'abord ton jeton TMDB dans les paramètres.");el.settings.showModal();e.target.value="";return;}try{const data=JSON.parse(await file.text());if(!Array.isArray(data.shows))throw Error("Fichier non reconnu : choisis l'export JSON Serializd avec les séries.");const diary=Array.isArray(data.diary)?data.diary:[];const latest=new Map();for(const d of diary){if(d.showId==null)continue;const prev=latest.get(String(d.showId));if(!prev||String(d.dateAdded||"")>String(prev.dateAdded||""))latest.set(String(d.showId),d);}let added=0,updated=0;for(const s of data.shows){const name=s.name||s.showName;if(!name||typeof name!=="string")continue;const fromTVTime=data.source==="TV Time export";let found=state.items.find(x=>fromTVTime?x.tvtimeId===String(s.showId):x.serializdId===String(s.showId)||x.name.toLocaleLowerCase("fr")===name.toLocaleLowerCase("fr"));if(!found)found=state.items.find(x=>!x.tvtimeId&&!x.serializdId&&x.type==="tv"&&x.name.toLocaleLowerCase("fr")===name.toLocaleLowerCase("fr"));let tmdbId=found?.tmdbId||null,poster=found?.poster||null;if(!tmdbId){const res=await tmdb("/search/tv?query="+encodeURIComponent(name)+"&language="+(state.language||"fr-FR"));const norm=v=>String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("fr").trim();const hit=(res.results||[]).find(x=>norm(x.name)===norm(name))||(res.results||[])[0];if(!hit&&!fromTVTime)continue;tmdbId=hit?String(hit.id):null;poster=hit?.poster_path||null;}const log=latest.get(String(s.showId));let season=1,episode=1;if(log){const se=log.season||{},ep=log.episode||{};season=Number(se.seasonNumber)||1;episode=(Number(ep.episodeNumber)||0)+1;}if(found){found.tmdbId=tmdbId||found.tmdbId||null;found.poster=poster||found.poster;if(log)found.progress={season,episode};if(!found.completed)found.active=true;if(fromTVTime)found.tvtimeId=String(s.showId);else found.serializdId=String(s.showId);updated++;}else{state.items.push({id:crypto.randomUUID?crypto.randomUUID():Date.now()+"-"+Math.random(),tmdbId,type:"tv",name,poster,active:true,completed:false,progress:{season,episode},lastEpisode:null,...(fromTVTime?{tvtimeId:String(s.showId)}:{serializdId:String(s.showId)}),addedAt:Date.now()});added++;}}save();render();toast("Import Serializd terminé : "+added+" ajoutée(s), "+updated+" mise(s) à jour.");}catch(err){toast(err.message||"Impossible de lire ce fichier.");}finally{e.target.value="";}});
async function exportBackup(){
const payload={format:"serie-au-hasard-backup",version:1,exportedAt:new Date().toISOString(),items:state.items,recommendations:state.recommendations||[],watchHistory:state.watchHistory||[],history:state.history,lastId:state.lastId,language:state.language||"fr-FR"};
const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});
const stamp=new Date().toISOString().slice(0,10),filename="serie-au-hasard-sauvegarde-"+stamp+".json";
try{
if(typeof File!=="undefined"&&navigator.share&&navigator.canShare){
const file=new File([blob],filename,{type:"application/json"});
if(navigator.canShare({files:[file]})){
await navigator.share({files:[file],title:"Sauvegarde Série au hasard"});
$("backup-note").textContent="Choisis « Enregistrer dans Fichiers » pour conserver ta sauvegarde.";
return;
}
}
}catch(err){
if(err&&err.name==="AbortError"){$("backup-note").textContent="Export annulé. Tes données sont toujours dans l’application.";return;}
}
const url=URL.createObjectURL(blob),a=document.createElement("a");
a.href=url;a.download=filename;a.style.display="none";document.body.appendChild(a);a.click();a.remove();
// Safari peut avoir besoin de conserver l’URL du fichier après le clic.
setTimeout(()=>URL.revokeObjectURL(url),60000);
$("backup-note").textContent="Téléchargement lancé. Sur iPhone, vérifie l’app Fichiers, dossier Téléchargements.";
}
async function importBackup(file){
if(!file)return;const note=$("backup-note");
try{
if(file.size>20*1024*1024)throw Error("Fichier trop volumineux (maximum 20 Mo).");
const raw=JSON.parse(await file.text());
const importedItems=Array.isArray(raw)?raw:(raw?.items||raw?.data?.items||raw?.series);
const importedWatchHistory=Array.isArray(raw?.watchHistory)?raw.watchHistory:[];const importedHistory=Array.isArray(raw?.history)?raw.history:[];const importedRecommendations=Array.isArray(raw?.recommendations)?raw.recommendations:[];
if(!Array.isArray(importedItems))throw Error("Format non reconnu. Sélectionne une sauvegarde JSON de Série au hasard.");
if(!confirm("Importer "+importedItems.length+" titre(s) ? Ta bibliothèque actuelle sera conservée et les doublons fusionnés."))return;
let added=0,updated=0,skipped=0;
for(const incoming of importedItems){if(!incoming||typeof incoming.name!=="string"||!incoming.name.trim()||!["tv","movie"].includes(incoming.type)){skipped++;continue;}const match=state.items.find(x=>x.id===incoming.id||(incoming.tmdbId&&String(x.tmdbId)===String(incoming.tmdbId)&&x.type===incoming.type));const clean={...incoming,id:match?.id||incoming.id||((crypto.randomUUID&&crypto.randomUUID())||Date.now()+"-"+Math.random()),progress:incoming.type==="tv"?{season:Math.max(1,Number(incoming.progress?.season)||1),episode:Math.max(1,Number(incoming.progress?.episode)||1)}:incoming.progress,active:incoming.active!==false,addedAt:Number(incoming.addedAt)||Date.now()};if(match){Object.assign(match,clean);updated++;}else{state.items.push(clean);added++;}}
const seen=new Set(state.history.map(h=>[h.name,h.date,h.detail].join("|")));for(const h of importedHistory){if(h&&typeof h.name==="string"){const key=[h.name,h.date,h.detail].join("|");if(!seen.has(key)){state.history.push(h);seen.add(key);}}}state.history=state.history.slice(0,100);const watchIds=new Set(state.watchHistory.map(v=>v.id));for(const v of importedWatchHistory){if(v&&v.id&&!watchIds.has(v.id)){state.watchHistory.push(v);watchIds.add(v.id);}}state.watchHistory=state.watchHistory.slice(-300);for(const rec of importedRecommendations){if(rec&&typeof rec.name==="string"&&["tv","movie"].includes(rec.type)&&!state.recommendations.some(x=>(rec.tmdbId&&String(x.tmdbId)===String(rec.tmdbId)&&x.type===rec.type)||x.name.toLocaleLowerCase("fr")===rec.name.toLocaleLowerCase("fr"))){state.recommendations.push({...rec,id:rec.id||((crypto.randomUUID&&crypto.randomUUID())||Date.now()+"-"+Math.random())});}}if(raw?.lastId&&!state.items.some(x=>x.id===raw.lastId))state.lastId=null;
save();render();note.textContent="Import réussi : "+added+" ajout(s), "+updated+" mise(s) à jour"+(skipped?" · "+skipped+" ignoré(s)":"")+".";toast("Sauvegarde importée : "+(added+updated)+" titre(s).");
}catch(err){note.textContent=err.message||"Impossible de lire ce fichier JSON.";toast("Import impossible : "+(err.message||"fichier invalide"));}
}

